"""Shared original-child ownership; used only by the two explicit supervisors."""
import base64
import hashlib
import json
import os
import selectors
import signal
import subprocess
import time

STOP = []
RETAINED = []


def need(ok, message):
    if not ok:
        raise RuntimeError(message)


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def canonical(value):
    return (json.dumps(value,sort_keys=True,separators=(',',':'))+'\n').encode()


def defer(signum, _frame):
    STOP.append({'signal':signal.Signals(signum).name,'monotonic_ns':time.monotonic_ns()})


def install_handlers():
    need(signal.getsignal(signal.SIGCHLD)==signal.SIG_DFL,'default SIGCHLD required for original custody')
    for signum in (signal.SIGINT,signal.SIGTERM,signal.SIGHUP):
        signal.signal(signum,defer)


class Owned:
    """Own one original Popen; only this object may consume its original wait4."""
    def __init__(self, argv, env, *, maximum=2*1024*1024, sinks=None):
        self.argv,self.env,self.maximum=argv,env,maximum
        self.child=self.pidfd=None
        self.selector=selectors.DefaultSelector()
        self.pipes={}
        self.pending=[]
        self.sinks={} if sinks is None else sinks
        self.captured={'stdout':bytearray(),'stderr':bytearray()}
        self.row={'argv':argv,'original_wait4':None,'custody_uncertain':False,'signals':[],
                  'cleanup_errors':[],'packets':[],'stdout_eof':False,'stderr_eof':False,
                  'discarded_bytes':{'stdout':0,'stderr':0}}
        self.began=time.monotonic()

    def cleanup_error(self, message):
        if message not in self.row['cleanup_errors']:
            self.row['cleanup_errors'].append(message)

    def start(self, *, fail_pidfd=False):
        need(self.child is None,'an original process cannot be replaced')
        self.child=subprocess.Popen(self.argv,stdin=subprocess.PIPE,stdout=subprocess.PIPE,
                                    stderr=subprocess.PIPE,bufsize=0,start_new_session=True,env=self.env)
        self.row['original_popen_pid']=self.child.pid
        # Establish ownership of all three original streams before any setup
        # operation that can fail, including pidfd/nonblocking/registration.
        self.pipes={name:getattr(self.child,name) for name in ('stdin','stdout','stderr')}
        for name in ('stdin','stdout','stderr'):
            stream=self.pipes[name]
            os.set_blocking(stream.fileno(),False)
            if name!='stdin':self.selector.register(stream,selectors.EVENT_READ,name)
        if fail_pidfd:raise OSError('injected original pidfd setup failure')
        self.pidfd=os.pidfd_open(self.child.pid,0)
        self.row['original_pidfd_bound']=True

    def close_pipe(self, name):
        stream=self.pipes.pop(name,None)
        if stream is not None:
            try:self.selector.unregister(stream.fileno())
            except (ValueError,KeyError):pass
            except OSError as error:self.cleanup_error('original selector unregister: '+str(error))
            try:stream.close()
            except OSError as error:self.cleanup_error('original pipe close: '+str(error))

    def queue(self, kind, raw):
        need('stdin' in self.pipes and not self.pending,'one bounded packet at a time required')
        need(0<len(raw)<=131072,'control packet outside bound')
        row={'kind':kind,'bytes':len(raw),'sha256':digest(raw),'bytes_written':0}
        self.row['packets'].append(row)
        self.pending.append((raw,row))
        self.selector.register(self.pipes['stdin'],selectors.EVENT_WRITE,'stdin')
        return row

    def reap(self):
        if self.child is None or self.row['original_wait4'] is not None or self.row['custody_uncertain']:
            return
        try:pid,status,usage=os.wait4(self.child.pid,os.WNOHANG)
        except InterruptedError:return
        except ChildProcessError:
            self.row['custody_uncertain']=True
            self.row['cleanup_errors'].append('ECHILD: original wait4 unavailable; no further PID signal')
            return
        except OSError as error:
            self.row['custody_uncertain']=True
            self.cleanup_error('original wait4 failed: '+str(error));return
        if pid:
            need(pid==self.child.pid,'wait4 returned a different child')
            self.child.returncode=os.waitstatus_to_exitcode(status)
            self.row['original_wait4']={'pid':pid,'raw_status':status,'exit_code':self.child.returncode,
                                      'user_seconds':usage.ru_utime,'system_seconds':usage.ru_stime,
                                      'maxrss_kib':usage.ru_maxrss}

    def pump(self, seconds=.05):
        try:events=self.selector.select(max(0,seconds))
        except InterruptedError:events=[]
        for key,_events in events:
            name=key.data
            if name=='stdin':
                raw,row=self.pending[0]
                try:
                    count=os.write(key.fd,raw[row['bytes_written']:]);row['bytes_written']+=count
                except BlockingIOError:continue
                except (BrokenPipeError,ConnectionResetError):
                    self.row.setdefault('stdin_errors',[]).append('original control pipe closed before packet completed')
                    self.close_pipe('stdin');continue
                if row['bytes_written']==len(raw):
                    self.pending.pop(0);self.selector.unregister(key.fd)
            else:
                try:data=os.read(key.fd,65536)
                except (BlockingIOError,InterruptedError):continue
                except OSError as error:
                    self.row['cleanup_errors'].append(name+' read: '+str(error));self.close_pipe(name);continue
                if not data:
                    self.row[name+'_eof']=True;self.close_pipe(name);continue
                room=max(0,self.maximum-len(self.captured[name]))
                self.captured[name].extend(data[:room]);self.row['discarded_bytes'][name]+=max(0,len(data)-room)
                if name in self.sinks and room:
                    try:
                        part=data[:room]
                        count=self.sinks[name].write(part)
                        need(count==len(part),'original stream evidence write incomplete')
                    except (OSError,RuntimeError) as error:
                        self.row['cleanup_errors'].append(name+' evidence write: '+str(error))
                        self.sinks.pop(name,None)
        self.reap()

    def complete(self):
        return bool(self.row['original_wait4'] and self.row['stdout_eof'] and self.row['stderr_eof'])

    def sound(self):
        need(not self.row['custody_uncertain'] and not self.row['cleanup_errors']
             and not any(self.row['discarded_bytes'].values()),'original child I/O/custody incomplete')

    def signal_original(self, number):
        self.reap()
        if self.child is None or self.row['original_wait4'] or self.row['custody_uncertain']:
            return
        try:
            if self.pidfd is not None:
                signal.pidfd_send_signal(self.pidfd,number);target='original_pidfd'
            else:
                os.kill(self.child.pid,number);target='original_unreaped_Popen'
            self.row['signals'].append({'signal':signal.Signals(number).name,'target':target,
                                        'at_seconds':time.monotonic()-self.began})
        except ProcessLookupError:pass
        except OSError as error:self.row['cleanup_errors'].append('original signal: '+str(error))

    def wait_until(self, deadline):
        while not self.complete() and not self.row['custody_uncertain'] and time.monotonic()<deadline:
            try:self.pump(min(.05,max(0,deadline-time.monotonic())))
            except BaseException as error:
                self.cleanup_error('original cleanup pump: '+type(error).__name__+': '+str(error))
                # I/O/select failure cannot discard original process custody.
                # Keep observing only this child's wait4 under the same deadline.
                try:self.reap()
                except BaseException as inner:
                    self.row['custody_uncertain']=True
                    self.cleanup_error('original cleanup reap: '+str(inner))
                time.sleep(min(.02,max(0,deadline-time.monotonic())))

    def finish(self):
        try:self.reap()
        except BaseException as error:
            self.row['custody_uncertain']=True;self.cleanup_error('original final reap: '+str(error))
        for name in list(self.pipes):
            try:self.close_pipe(name)
            except BaseException as error:self.cleanup_error('original final pipe close: '+str(error))
        try:self.selector.close()
        except BaseException as error:self.cleanup_error('original selector close: '+str(error))
        if self.child is not None and self.row['original_wait4'] is None:
            RETAINED.append((self.child,self.pidfd));self.pidfd=None
            self.row['cleanup_errors'].append('original child not reaped; custody retained as unknown')
        if self.pidfd is not None:
            try:os.close(self.pidfd)
            except OSError as error:self.cleanup_error('original pidfd close: '+str(error))
            self.pidfd=None
        for name in ('stdout','stderr'):
            raw=bytes(self.captured[name])
            self.row[name+'_bytes']=len(raw)
            self.row[name+'_sha256']=digest(raw)
            self.row[name+'_original']=raw.decode('utf-8',errors='replace')
            self.row[name+'_original_base64']=base64.b64encode(raw).decode('ascii')
        for row in self.row['packets']:
            row['write_state']=('not_written' if row['bytes_written']==0 else
                                'fully_written' if row['bytes_written']==row['bytes'] else 'partial_unknown')
        self.row['wall_seconds']=time.monotonic()-self.began
        self.row['cleanup_complete']=bool(self.complete() and not self.row['custody_uncertain']
                                          and not self.row['cleanup_errors'] and not any(self.row['discarded_bytes'].values()))
        return self.row


def abort_driver(child, *, grace=80, forced=10):
    """Give the original driver its existing helper cleanup window, once."""
    if child.child is None:return
    began=time.monotonic()
    state=child.row.setdefault('driver_abort',{'started_monotonic':began,'grace_seconds':grace,
            'forced_seconds':forced,'grace_deadline':began+grace,'forced_deadline':began+grace+forced,
            'interrupt_requested':False,'kill_requested':False})
    need(state['grace_seconds']==grace and state['forced_seconds']==forced,'cleanup policy cannot change')
    child.close_pipe('stdin')
    if not state['interrupt_requested']:
        state['interrupt_requested']=True
        child.signal_original(signal.SIGINT)
    child.wait_until(state['grace_deadline'])
    if not child.complete() and not child.row['custody_uncertain']:
        if not state['kill_requested']:
            state['kill_requested']=True
            child.signal_original(signal.SIGKILL)
        child.wait_until(state['forced_deadline'])


def close_ssh(child, *, grace=110, forced=10):
    """EOF requests remote cleanup while SSH and its agent forwarding stay live."""
    if child.child is None:return
    began=time.monotonic()
    state=child.row.setdefault('ssh_close',{'started_monotonic':began,'grace_seconds':grace,
            'forced_seconds':forced,'eof_deadline':began+grace,'term_deadline':began+grace+forced/2,
            'kill_deadline':began+grace+forced,'term_requested':False,'kill_requested':False})
    need(state['grace_seconds']==grace and state['forced_seconds']==forced,'cleanup policy cannot change')
    child.close_pipe('stdin')
    child.wait_until(state['eof_deadline'])
    if not child.complete() and not child.row['custody_uncertain']:
        if not state['term_requested']:
            state['term_requested']=True
            child.signal_original(signal.SIGTERM)
        child.wait_until(state['term_deadline'])
    if not child.complete() and not child.row['custody_uncertain']:
        if not state['kill_requested']:
            state['kill_requested']=True
            child.signal_original(signal.SIGKILL)
        child.wait_until(state['kill_deadline'])

