def need(ok, message):
    if not ok:
        raise RuntimeError(message)


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def deferred_signal(number, _frame):
    STOP.append(signal.Signals(number).name)


def public_receipt(path, expected):
    p = Path(path)
    need(p == p.resolve(strict=True), 'public source path is indirect')
    before = p.lstat()
    need(stat.S_ISREG(before.st_mode) and before.st_uid == 1000 and before.st_nlink == 1
         and not before.st_mode & 0o022 and before.st_size <= 65536, 'public source metadata differs')
    raw = p.read_bytes()
    after = p.lstat()
    ident = lambda s: [s.st_dev,s.st_ino,s.st_uid,s.st_mode,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns]
    need(ident(before) == ident(after) and sha(raw) == expected, 'pinned public source changed')
    return {'path':path,'bytes':len(raw),'sha256':expected,'identity':ident(before)}


def owned_child(argv, payload, seconds, *, env=None, injected_pidfd_failure=False):
    """No poll/communicate/wait or other reaper can consume the original wait4."""
    need(signal.getsignal(signal.SIGCHLD) == signal.SIG_DFL, 'original-child custody requires default SIGCHLD')
    began = time.monotonic()
    row = {'argv':argv,'signals':[],'cleanup_errors':[],'stdin_bytes':len(payload),
           'stdin_sha256':sha(payload),'stdin_bytes_written':0,'original_wait4':None,
           'stdout_eof':False,'stderr_eof':False,'custody_uncertain':False}
    child = None
    handle = None
    sel = selectors.DefaultSelector()
    captures = {'stdout':bytearray(),'stderr':bytearray()}
    discarded = {'stdout':0,'stderr':0}
    pipes = {}

    def reap():
        if row['original_wait4'] is not None or row['custody_uncertain']:
            return
        try:
            pid, status, usage = os.wait4(child.pid, os.WNOHANG)
        except ChildProcessError:
            row['custody_uncertain'] = True
            row['cleanup_errors'].append('original wait4 custody lost; no further PID signal')
            return
        if pid:
            need(pid == child.pid, 'wait4 returned another child')
            child.returncode = os.waitstatus_to_exitcode(status)
            row['original_wait4'] = {'pid':pid,'raw_status':status,'exit_code':child.returncode,
                                    'user_seconds':usage.ru_utime,'system_seconds':usage.ru_stime,
                                    'maxrss_kib':usage.ru_maxrss}

    def close_pipe(name):
        stream = pipes.pop(name, None)
        if stream is not None:
            try: sel.unregister(stream.fileno())
            except (KeyError, ValueError): pass
            stream.close()

    def pump(wait):
        for key, _events in sel.select(max(0, wait)):
            name = key.data
            if name == 'stdin':
                try:
                    n = os.write(key.fd, payload[row['stdin_bytes_written']:])
                    row['stdin_bytes_written'] += n
                    if row['stdin_bytes_written'] == len(payload): close_pipe('stdin')
                except BrokenPipeError:
                    close_pipe('stdin')
            else:
                try: data = os.read(key.fd, 16384)
                except BlockingIOError: continue
                if not data:
                    row[name+'_eof'] = True; close_pipe(name); continue
                room = max(0, 65536-len(captures[name]))
                captures[name].extend(data[:room]); discarded[name] += max(0,len(data)-room)
        reap()

    try:
        child = subprocess.Popen(argv, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                 stderr=subprocess.PIPE, bufsize=0, env=env, start_new_session=True)
        row['original_popen_pid'] = child.pid
        for name in ('stdin','stdout','stderr'):
            stream = getattr(child,name); pipes[name] = stream
            os.set_blocking(stream.fileno(),False)
            sel.register(stream,selectors.EVENT_WRITE if name=='stdin' else selectors.EVENT_READ,name)
        if not payload: close_pipe('stdin')
        if injected_pidfd_failure: raise OSError('injected original pidfd setup failure')
        handle = os.pidfd_open(child.pid,0)
        row['original_pidfd_bound'] = True
        deadline = began+seconds
        while not (row['original_wait4'] and row['stdout_eof'] and row['stderr_eof']):
            need(not STOP,'stop requested')
            need(time.monotonic()<deadline,'original short-child deadline')
            pump(min(.02,deadline-time.monotonic()))
            need(not row['custody_uncertain'],'original child custody uncertain')
            need(not any(discarded.values()),'bounded original output exceeded')
        need(row['stdin_bytes_written']==len(payload),'original script input was not fully written')
    except BaseException as error:
        row['error'] = type(error).__name__+': '+str(error)
    finally:
        if child is not None:
            # One original cleanup deadline; extra signals do not renew it.
            cleanup_deadline = time.monotonic()+5
            close_pipe('stdin')
            reap()
            if row['original_wait4'] is None and not row['custody_uncertain']:
                try:
                    if handle is not None:
                        signal.pidfd_send_signal(handle,signal.SIGKILL)
                        row['signals'].append('SIGKILL_original_pidfd')
                    else:
                        os.kill(child.pid,signal.SIGKILL)
                        row['signals'].append('SIGKILL_original_unreaped_Popen')
                except ProcessLookupError: pass
                except OSError as error: row['cleanup_errors'].append('original signal: '+str(error))
            while time.monotonic()<cleanup_deadline and not (
                row['original_wait4'] and row['stdout_eof'] and row['stderr_eof']):
                pump(min(.02,cleanup_deadline-time.monotonic()))
                if row['custody_uncertain']: break
            if row['original_wait4'] is None:
                row['cleanup_errors'].append('no authoritative original wait4 completion')
                RETAINED.append((child,handle)); handle=None
        for name in list(pipes): close_pipe(name)
        sel.close()
        if handle is not None: os.close(handle)
        row['wall_seconds'] = time.monotonic()-began
        row['discarded_bytes'] = discarded
        for name in ('stdout','stderr'):
            data=bytes(captures[name]); row[name+'_original']=data.decode('utf-8',errors='replace')
            row[name+'_sha256']=sha(data); row[name+'_bytes']=len(data)
        row['cleanup_complete'] = bool(row['original_wait4'] and row['stdout_eof'] and row['stderr_eof']
                                       and not row['cleanup_errors'] and not row['custody_uncertain'])
    return row


