         and q['source']==str(SOURCE),'actual A54 r01 qualification required before fixture')
    mapping=q['source_tested']
    need(mapping==q['source_after'] and len(mapping)==175 and set(mapping)==set(q['source_input'])
         and digest(json.dumps(q['source_input'],sort_keys=True,separators=(',',':')).encode())==PREPARED_SHA
         and digest(json.dumps(mapping,sort_keys=True,separators=(',',':')).encode())==plan['source_map_compact_sha256'],
         'actual A54 r01 source maps differ')
    need([s['name'] for s in q['stages']]==['format','fmt-check','clean-package','clippy','test','release']
         and all(s['returncode']==0 for s in q['stages']),'original six qualification stages incomplete')
    inventory=set()
    for directory,dirs,files in os.walk(SOURCE,followlinks=False):
        need(all(stat.S_ISDIR((Path(directory)/n).lstat().st_mode) for n in dirs),'source directory symlink')
        for name in files:inventory.add((Path(directory)/name).relative_to(SOURCE).as_posix())
    need(inventory==set(mapping),'current A54 source inventory differs')
    for name,expected in sorted(mapping.items()):
        relative=Path(name)
        need(not relative.is_absolute() and '..' not in relative.parts,'unsafe source mapping')
        read(SOURCE/relative,expected,maximum=16*1024*1024)
    for key in ('binary','test_binary'):
        item=q[key]
        need(item['cached'] is False and Path(item['path']).parent==QUALIFICATION.parent
             and item['compiler_source']==str(SOURCE/'src/main.rs'),'original r01 compiler artifact differs')
        read(item['path'],item['sha256'])
    need(q['binary']['sha256']==plan['elf_sha256'],'actual r01 ELF differs')
    baseline=Path(plan['baseline']['path'])
    need(baseline.is_relative_to(PROJECT) and baseline.name=='report.json'
         and plan['baseline']['sha256']==BASELINE_SHA,'original A40 baseline binding differs')
    bq=json.loads(read(baseline,BASELINE_SHA,contents=True,maximum=1024*1024))
    need(bq['qualified'] is True and bq['current_stage']=='complete' and not bq.get('error')
         and bq['binary']['cached'] is False,'original A40 qualification incomplete')
    need(Path(bq['binary']['path']).is_relative_to(PROJECT),'A40 binary outside original development tree')
    read(bq['binary']['path'],bq['binary']['sha256'])
    driver_raw=read(DRIVER,plan['driver']['sha256'],contents=True,maximum=131072)
    bind=json.loads(read(BINDING,plan['binding']['sha256'],contents=True,maximum=1024*1024))
    need(bind['schema']=='hepta-a54-six-host-binding-adapter/v1' and bind['ready'] is True
         and bind['binding_only_reversal_verified'] is True
         and bind['parent_driver_sha256']=='6123660947b4b205d7f70d901c4e78b74395df065226a27937730b8c4cdd2ec9'
         and bind['candidate']['qualification_sha256']==plan['qualification']['sha256']
         and bind['candidate']['release_sha256']==plan['elf_sha256']
         and bind['candidate']['source_files']==175
         and bind['driver']['sha256']==plan['driver']['sha256'],'actual binding-only original driver required')
    constants={}
    for node in ast.parse(driver_raw).body:
        if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name):
            if node.targets[0].id in ('HOSTS','STAGE_LAYOUT','FINAL_BINDINGS_READY','R07_QUALIFICATION_SHA','R07_SOURCE_MAP_SHA','R07_RELEASE_SHA'):
                constants[node.targets[0].id]=ast.literal_eval(node.value)
    need(constants=={'HOSTS':HOSTS,'STAGE_LAYOUT':LAYOUT,'FINAL_BINDINGS_READY':True,
                     'R07_QUALIFICATION_SHA':plan['qualification']['sha256'],
                     'R07_SOURCE_MAP_SHA':plan['source_map_compact_sha256'],'R07_RELEASE_SHA':plan['elf_sha256']},
         'original six-host/eight-stage/binding protocol differs')
    for name,expected in HELPERS.items():read(DEV/'tools'/name,expected,maximum=131072)
    job_paths=sorted(JOBS.glob('*.json'));need(len(job_paths)==6,'six original frozen jobs required')
    seen=[]
    for path in job_paths:
        job=json.loads(read(path,contents=True,maximum=131072))
        need(path.name==job['id']+'.json' and job['launch_state']=='launched'
             and job['execution_mode']=='operator' and job['system_jobctl'] is False
             and job['ssh_target']=='hepta-native-test-v7-'+job['host']
             and re.fullmatch('HEPTA-A16-ONCE-'+re.escape(job['host'])+'-[0-9a-f]{24}',job['args'][-1]),
             'original frozen synthetic job differs')
        seen.append(job['host'])
    need(tuple(sorted(seen))==HOSTS,'fixed six-host job membership differs')
    need(agent==forward['agent_frame'](agent['socket']) and public==[forward['public_receipt'](p,h) for p,h in PUBLIC.items()],
         'agent/public input changed during admission')
    return {'agent':agent,'public':public,'input_receipts':receipts,'source_map':mapping,
            'candidate_qualification_sha256':plan['qualification']['sha256'],'candidate_elf_sha256':plan['elf_sha256']}


def remote_main():
    parser=argparse.ArgumentParser();parser.add_argument('--plan-sha256',required=True);args=parser.parse_args()
    install_handlers();os.set_blocking(1,False)
    control=Control();child=None;sinks={};created=False;accepted=False;native_raw=None
    report={'schema':'hepta-a54-six-host-remote-owned-lease/v1','passed':False,'errors':[],
            'plan_sha256':args.plan_sha256,'start_committed':False,'driver_spawn_attempted':False,
            'automatic_retries':0,'configuration_changes':0,'private_key_reads':0,'agent_loads':0}
    try:
        message=control.one(15)
        need(message.get('op')=='plan' and message.get('seq')==0 and message.get('plan_sha256')==args.plan_sha256,
             'original frozen plan packet required')
        raw=base64.b64decode(message['base64'],validate=True)
        need(len(raw)<=65536 and digest(raw)==args.plan_sha256,'frozen plan bytes differ')
        plan=json.loads(raw);admission=admit(plan)
        report['admission']=admission
        emit({'event':'ready','seq':0,'plan_sha256':args.plan_sha256,'agent':admission['agent'],
              'qualification_sha256':plan['qualification']['sha256'],'elf_sha256':plan['elf_sha256'],
              'source_map_compact_sha256':plan['source_map_compact_sha256'],'source_files':175})
        start=control.one(20)
        need(start=={'op':'start','seq':1,'plan_sha256':args.plan_sha256,'nonce':plan['nonce']},
             'one original start commitment required')
        need(not STOP,'stop requested before original driver commitment')
        report['start_committed']=True
        os.umask(0o077);LEASE.mkdir(mode=0o700);created=True
        create(LEASE/'plan.original.json',raw);create(LEASE/'admission.original.json',canonical(admission))
        argv=['/usr/bin/python3','-I','-S','-B',str(DRIVER),'--qualification',str(QUALIFICATION),
              '--baseline-qualification',plan['baseline']['path'],'--tools-dir',str(DEV/'tools'),
              '--profile-template',str(PROFILE),'--frozen-jobs',str(JOBS),
              '--out',str(OUT),'--socket-parent',str(SOCKET_PARENT)]
        env={'PATH':'/usr/bin:/bin','LANG':'C','SHELL':'/bin/sh','SSH_AUTH_SOCK':admission['agent']['socket'],
             'PYTHONDONTWRITEBYTECODE':'1','PYTHONNOUSERSITE':'1'}
        for name in ('stdout','stderr'):
            sinks[name]=(LEASE/('driver.'+name+'.original')).open('xb',buffering=0)
        child=Owned(argv,env,sinks=dict(sinks));report['driver_spawn_attempted']=True
        child.start();child.close_pipe('stdin')
        active_deadline=time.monotonic()+BUDGETS['driver_active']
        last_heartbeat=time.monotonic();last_seq=1
        emit({'event':'started','seq':1,'plan_sha256':args.plan_sha256,
              'driver_original_pid':child.child.pid,'active_seconds':BUDGETS['driver_active']})
        while not child.complete():
            need(not STOP,'remote supervisor stop requested')
            need(time.monotonic()<active_deadline,'original driver envelope expired')
            need(time.monotonic()-last_heartbeat<BUDGETS['heartbeat_timeout'],'original main heartbeat expired')
            for packet in control.poll():
                need(packet.get('plan_sha256')==args.plan_sha256 and packet.get('seq')==last_seq+1,
                     'original control sequence changed')
                last_seq=packet['seq']
                need(packet.get('op')=='heartbeat','control stop or invalid repeated start')
                last_heartbeat=time.monotonic()
                emit({'event':'heartbeat','seq':last_seq,'plan_sha256':args.plan_sha256})
            need(not control.eof,'main control EOF: stop original driver while forwarding session is held')
            child.pump(.05);child.sound()
        accepted=True
    except BaseException as error:
        report['errors'].append(type(error).__name__+': '+str(error))
    finally:
        if child is not None:
            try:
                if not accepted or not child.complete():abort_driver(child)
            except BaseException as error:report['errors'].append('original driver cleanup: '+str(error))
            try:report['driver_original_child']=child.finish()
            except BaseException as error:
                RETAINED.append(child)
                report['errors'].append('original driver finalization: '+str(error))
                report['driver_original_child']={**child.row,'cleanup_complete':False}
        for stream in sinks.values():
            try:stream.flush();os.fsync(stream.fileno());stream.close()
            except OSError as error:report['errors'].append('original evidence flush: '+str(error))
        report['control_packets']=control.records;report['stop_signals']=STOP
        if created:
            try:
                if (OUT/'report.json').exists():
                    native_raw,receipt=original(OUT/'report.json',contents=True,maximum=16*1024*1024)
                    native=json.loads(native_raw);report['native_report']=receipt
                    report['native_summary']={k:native.get(k) for k in ('schema','passed','complete','failed_stage','error','unexecuted_count','integrity_assertions','a54_binding')}
                if accepted and not report['errors']:
                    row=report['driver_original_child']
                    need(row['cleanup_complete'] and row['original_wait4']['exit_code']==0
                         and not row['signals'] and not STOP,'original driver did not finish cleanly')
                    need(native_raw is not None and native['schema']=='hepta-a54-native-validation-series/v1'
                         and native['passed'] is True and native['complete'] is True and not native.get('error')
                         and native['unexecuted_count']==0 and len(native['stages'])==8
                         and all(v is True for v in native['integrity_assertions'].values())
                         and all(s['status']=='passed' and s['execution_count']==1 and s['custody_retained_until_reap'] is True
                                 and s['returncode']==0 and s['timed_out'] is False for s in native['stages']),
                         'complete unchanged eight-stage gate did not pass')
                    for item in admission['input_receipts']:
                        _,after=original(item['path'],item['sha256']);need(after==item,'original input changed through lease')
                    need(admission['agent']==forward['agent_frame'](admission['agent']['socket'])
                         and admission['public']==[forward['public_receipt'](p,h) for p,h in PUBLIC.items()],
                         'original forwarded agent/public source changed through lease')
                    report['passed']=True
            except BaseException as error:report['errors'].append(type(error).__name__+': '+str(error))
            report['passed']=report['passed'] and not report['errors']
            try:
                create(LEASE/'report.json',canonical(report))
                _,report_receipt=original(LEASE/'report.json')
            except BaseException as error:
                report['passed']=False;report_receipt=None
                report['errors'].append('remote supervisor evidence persistence: '+str(error))
        else:report_receipt=None
        final={'event':'final','plan_sha256':args.plan_sha256,'passed':report['passed'],
               'report':report_receipt,'start_committed':report['start_committed'],
               'driver_spawn_attempted':report['driver_spawn_attempted'],
               'driver_original_child':report.get('driver_original_child'),
               'native_report':report.get('native_report'),'native_summary':report.get('native_summary'),
               'errors':report['errors'],'stop_signals':STOP}
        try:emit(final)
        except BaseException:pass
    return 0 if report['passed'] else 1


if __name__=='__main__':
    raise SystemExit(remote_main())
